const canvas=$('#game'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
const keys={},game={on:false,paused:false,over:false,time:60,last:0,round:0,effects:[],shake:0,announcement:0,players:[]};
function makeFighter(index,x,dir,isCPU,support){let c=cast[index];return{c,x,y:205,vx:0,vy:0,dir,health:100,chakra:0,guard:false,attack:0,attackType:'',cool:0,flash:0,stun:0,ai:rand(.35,1.1),supportCD:0,isCPU,isSupport:support,frame:0,ground:true}}
function startGame(){enemyIndex=(playerIndex+Math.ceil(Math.random()*(cast.length-1)))%cast.length;game.players=[makeFighter(playerIndex,142,1,false,supportIndex),makeFighter(enemyIndex,338,-1,true,0)];game.on=true;game.paused=false;game.over=false;game.time=60;game.round=0;game.effects=[];$('#pName').textContent=cast[playerIndex].name.toUpperCase();$('#eName').textContent=cast[enemyIndex].name.toUpperCase();$('#pSupport').textContent='SUPPORT  U · '+cast[(playerIndex+1+supportIndex)%cast.length].name.toUpperCase();$('#eSupport').textContent='SUPPORT READY';$('#specialName').textContent=cast[playerIndex].jutsu.toUpperCase().split(':')[0];$('#pause').classList.remove('open');show('match');announce('READY',700);setTimeout(()=>announce('FIGHT!',900),750);game.last=performance.now();requestAnimationFrame(loop)}
function announce(text,ms=850){let el=$('#announce');el.textContent=text;el.classList.add('show');clearTimeout(game.announcement);game.announcement=setTimeout(()=>el.classList.remove('show'),ms)}
function sound(freq=220,dur=.08,type='square'){if(muted)return;try{let ac=sound.ac||(sound.ac=new AudioContext()),o=ac.createOscillator(),g=ac.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.035,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+dur);o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+dur)}catch(e){}}
function effect(x,y,color,kind='burst'){game.effects.push({x,y,color,kind,life:30,max:30})}
function hit(attacker,move,damage,range=52){let target=game.players[attacker===game.players[0]?1:0];if(Math.abs(target.x-attacker.x)>range||Math.abs(target.y-attacker.y)>54)return false;if(target.guard&&target.dir===Math.sign(attacker.x-target.x)){damage*=.24;effect(target.x,target.y-26,'#78d8ff','spark');sound(130,.04)}else{target.health=Math.max(0,target.health-damage);target.stun=move==='ult'?50:12;target.vx=attacker.dir*(move==='ult'?4:2);target.flash=10;game.shake=move==='ult'?10:4;effect(target.x,target.y-24,move==='ult'?'#ffcd70':'#fff0c1',move==='ult'?'boom':'spark');sound(move==='ult'?100:160,.12,move==='ult'?'sawtooth':'square')}target.chakra=clamp(target.chakra+8,0,100);attacker.chakra=clamp(attacker.chakra+(move==='attack'?9:4),0,100);return true}
function doMove(f,type){if(!game.on||game.paused||game.over||f.cool>0||f.stun>0)return;if(type==='attack'){f.attack=18;f.attackType=type;f.cool=28;sound(290,.04)}else if(type==='special'){if(f.chakra<20)return;f.chakra-=20;f.attack=32;f.attackType=type;f.cool=48;game.effects.push({x:f.x+f.dir*25,y:f.y-29,color:'#78ddff',kind:'projectile',life:34,max:34,dir:f.dir,owner:f});sound(440,.13,'sawtooth')}else if(type==='ult'){if(f.chakra<50)return;f.chakra-=50;f.attack=50;f.attackType=type;f.cool=90;announce('ULTIMATE JUTSU!',900);game.effects.push({x:f.x+f.dir*30,y:f.y-28,color:'#ffc554',kind:'ultimate',life:45,max:45,dir:f.dir,owner:f});sound(75,.35,'sawtooth')}else if(type==='support'){if(f.supportCD>0)return;f.supportCD=260;let partner=f.isCPU?cast[(enemyIndex+1)%cast.length]:cast[(playerIndex+1+supportIndex)%cast.length];effect(f.x+f.dir*48,f.y-26,'#91e4ff','assist');game.effects.push({x:f.x+f.dir*48,y:f.y-26,color:'#a2e8ff',kind:'assist',life:25,max:25,dir:f.dir,owner:f,partner});let enemy=game.players[f.isCPU?0:1];if(Math.abs(enemy.x-f.x)<155){enemy.health=Math.max(0,enemy.health-8);enemy.stun=10;enemy.vx=f.dir*1.7;effect(enemy.x,enemy.y-24,'#adf1ff','spark')}sound(520,.11)} }
function input(){let p=game.players[0];if(!p)return;p.guard=!!keys.s;if(!p.stun){p.vx=(keys.a?-2.2:0)+(keys.d?2.2:0);if(p.vx)p.dir=Math.sign(p.vx);if(keys.w&&p.ground){p.vy=-6.4;p.ground=false;sound(360,.04)}}}
function cpuThink(e,dt){e.ai-=dt;if(e.ai>0)return;e.ai=rand(.3,.72);let p=game.players[0],distance=Math.abs(p.x-e.x);e.guard=distance<72&&Math.random()<.25;if(distance>75){e.vx=e.x>p.x?-1.35:1.35;e.dir=Math.sign(p.x-e.x)}else{e.vx=0;e.dir=Math.sign(p.x-e.x);if(Math.random()<.58)doMove(e,'attack');else if(e.chakra>24&&Math.random()<.62)doMove(e,'special');else if(e.chakra>=50&&Math.random()<.34)doMove(e,'ult');else if(Math.random()<.25)doMove(e,'support')}if(distance>120&&Math.random()<.35&&e.ground){e.vy=-6;e.ground=false}}
function update(dt){let [p,e]=game.players;if(!p||game.over)return;game.time=Math.max(0,game.time-dt);if(game.time===0){finish(p.health>=e.health?'YOU WIN':'CPU WINS');return}if(!p.isCPU)input();cpuThink(e,dt);for(let f of game.players){f.frame++;f.x+=f.vx;f.x=clamp(f.x,28,452);if(f.vy||!f.ground){f.y+=f.vy;f.vy+=.28;if(f.y>=205){f.y=205;f.vy=0;f.ground=true}}f.vx*=.77;if(f.cool>0)f.cool--;if(f.stun>0){f.stun--;f.vx*=.95}if(f.flash>0)f.flash--;if(f.supportCD>0)f.supportCD--;if(f.attack>0){f.attack--;if(f.attack===9&&f.attackType==='attack')hit(f,'attack',8,54);if(f.attack===18&&f.attackType==='special')hit(f,'special',12,80);if(f.attack===28&&f.attackType==='ult')hit(f,'ult',29,125)}}for(let fx of game.effects){fx.life--;if(fx.kind==='projectile'&&fx.life%5===0)hit(fx.owner,'special',3,55);if(fx.kind==='ultimate'&&fx.life===22)hit(fx.owner,'ult',20,160)}game.effects=game.effects.filter(f=>f.life>0);if(p.health<=0)finish('CPU WINS');else if(e.health<=0)finish('YOU WIN');$('#pHealth').style.width=p.health+'%';$('#eHealth').style.width=e.health+'%';$('#pChakra').style.width=p.chakra+'%';$('#eChakra').style.width=e.chakra+'%';$('#timer').textContent=Math.ceil(game.time);$('#ultAction').classList.toggle('ready',p.chakra>=50);$('#pSupport').textContent=p.supportCD?'SUPPORT RECHARGING':'SUPPORT READY · '+cast[(playerIndex+1+supportIndex)%cast.length].name.toUpperCase();}
function finish(text){if(game.over)return;game.over=true;announce(text,4000);setTimeout(()=>{$('#pauseTitle').textContent=text;$('#pause').classList.add('open')},1100)}

